insert into public.scenarios (category, difficulty, sender, sender_meta, subject, body, link, correct_answer, explanation, is_showcase, sender_en, sender_meta_en, subject_en, body_en, explanation_en) values
('sms'::scenario_category, 'easy'::difficulty_level, '+966 55 384 2917', '١١:٤٢ ص', null, 'عميلنا العزيز، شحنتك معلقة بسبب عدم اكتمال العنوان. ادفع ٩٫٥٠ ريال خلال ١٢ ساعة عبر الرابط:', 'spl-ksa-track.info/pay', 'scam'::answer_choice, 'رابط غريب، ومهلة قصيرة، ومبلغ صغير يطلبه منك.', false, null, '11:42 AM', null, 'Dear customer, your parcel is on hold because the address is incomplete. Pay 9.50 SAR within 12 hours at the link:', 'A strange link, a short deadline, and a small fee.'),
('sms'::scenario_category, 'easy'::difficulty_level, 'عيادة الأسنان', '٩:٣٠ ص', null, 'نذكرك بموعدك بكرة الأحد الساعة ٤:٣٠ م. للإلغاء رد على الرسالة برقم 2.', null, 'safe'::answer_choice, 'ما فيها رابط ولا تطلب بيانات، وجاية باسم العيادة.', false, 'Dental clinic', '9:30 AM', null, 'Reminder: your appointment is tomorrow, Sunday, at 4:30 PM. To cancel, reply 2.', 'No link, no request for details, and it comes from the clinic’s name.'),
('sms'::scenario_category, 'easy'::difficulty_level, '+966 59 004 3318', 'أمس', null, 'مبروك! فزت بجوال جديد في سحب عملاء الاتصالات. ادخل بياناتك لاستلام الجائزة:', 'win-gift-sa.co', 'scam'::answer_choice, 'ما دخلت أي سحب، والرابط مو موقع رسمي.', false, null, 'Yesterday', null, 'Congrats! You won a new phone in the telecom customer draw. Enter your details to claim it:', 'You never entered a draw, and the link isn’t an official site.'),
('sms'::scenario_category, 'easy'::difficulty_level, 'شركة الاتصالات', '٨:٠٥ م', null, 'تم شحن رصيدك بـ ١٠٠ ريال. رصيدك الحالي ١٢٣٫٥٠ ريال.', null, 'safe'::answer_choice, 'إشعار عن عملية سويتها، بدون رابط ولا طلب.', false, 'Telecom company', '8:05 PM', null, 'Your balance was topped up with 100 SAR. Current balance: 123.50 SAR.', 'A notice about something you did, with no link and no request.'),
('sms'::scenario_category, 'easy'::difficulty_level, '+966 53 220 4471', '١٠:١٠ ص', null, 'حسابك بيتوقف اليوم! أرسل رقم الهوية والرقم السري عشان نحدّثه.', null, 'scam'::answer_choice, 'ولا جهة تطلب رقمك السري برسالة.', false, null, '10:10 AM', null, 'Your account will be suspended today! Send your ID number and PIN so we can update it.', 'No organization asks for your PIN by message.'),
('sms'::scenario_category, 'easy'::difficulty_level, 'الصيدلية', '٦:٤٠ م', null, 'طلبك رقم 2290 جاهز للاستلام من الفرع حتى الساعة ١١ م.', null, 'safe'::answer_choice, 'معلومة عن طلب سويته، وما تطلب منك شيء.', false, 'Pharmacy', '6:40 PM', null, 'Your order 2290 is ready for pickup at the branch until 11 PM.', 'Info about an order you placed. It asks for nothing.'),
('sms'::scenario_category, 'easy'::difficulty_level, '+966 55 771 0093', 'أمس', null, 'مبروك! تم اختيار رقمك لجائزة ١٠٠٠٠ ريال. ادفع ٥٠ ريال رسوم تحويل:', 'prize-ksa-cash.com', 'scam'::answer_choice, 'الجائزة الحقيقية ما تطلب منك تدفع رسوم.', false, null, 'Yesterday', null, 'Congrats! Your number won a 10000 SAR prize. Pay a 50 SAR transfer fee:', 'A real prize never asks you to pay a fee.'),
('sms'::scenario_category, 'easy'::difficulty_level, 'شركة الكهرباء', 'الأحد', null, 'فاتورتك لشهر نوفمبر ٢١٥ ريال. تقدر تسددها من تطبيق البنك أو قنوات السداد المعتادة.', null, 'safe'::answer_choice, 'توجهك لقنوات سداد تعرفها، مو لرابط.', false, 'Electricity company', 'Sunday', null, 'Your November bill is 215 SAR. You can pay it from your banking app or the usual payment channels.', 'It points you to payment channels you know, not a link.'),
('sms'::scenario_category, 'easy'::difficulty_level, '+966 50 664 2318', '١٢:٣٠ م', null, 'تم إيقاف رقمك بسبب مخالفة. اتصل فوراً على 0900123456 لإعادة التفعيل.', null, 'scam'::answer_choice, 'رقم بمقدمة مدفوعة، وتهديد بإيقاف الخدمة.', false, null, '12:30 PM', null, 'Your number was suspended due to a violation. Call 0900123456 now to reactivate it.', 'A premium-rate number and a threat to cut your service.'),
('sms'::scenario_category, 'easy'::difficulty_level, 'المستشفى', 'الأحد', null, 'موعدك مع عيادة العيون الاثنين ١٠:١٥ ص. احضر قبل الموعد بـ ١٥ دقيقة.', null, 'safe'::answer_choice, 'تذكير بموعد، بدون رابط ولا طلب.', false, 'Hospital', 'Sunday', null, 'Your eye clinic appointment is Monday at 10:15 AM. Please arrive 15 minutes early.', 'An appointment reminder with no link and no request.'),
('sms'::scenario_category, 'easy'::difficulty_level, '+966 51 002 8812', '٤:٤٠ م', null, 'مرحباً، أنا من البنك. نشتبه بعملية على بطاقتك. بيوصلك رمز الحين، أرسله لنا عشان نلغي العملية.', null, 'scam'::answer_choice, 'البنك ما يطلب منك الرمز أبداً، حتى لو قال إنه يحميك.', false, null, '4:40 PM', null, 'Hi, I’m from the bank. We suspect a transaction on your card. You’ll get a code now. Send it to us so we can cancel it.', 'Banks never ask for your code, even when they say it’s to protect you.'),
('sms'::scenario_category, 'easy'::difficulty_level, 'شركة الكهرباء', 'الاثنين', null, 'تم استلام سدادك ٢١٥ ريال. شكراً لك.', null, 'safe'::answer_choice, 'تأكيد لدفعة سويتها، وما يطلب شيء.', false, 'Electricity company', 'Monday', null, 'We received your payment of 215 SAR. Thank you.', 'A receipt for a payment you made. It asks for nothing.'),
('sms'::scenario_category, 'medium'::difficulty_level, 'مصرفك', '١١:٤٠ ص', null, 'تم خصم ٢٤٥ ريال من بطاقتك المنتهية بـ 4417. إذا ما كانت العملية منك، اتصل على الرقم اللي خلف بطاقتك.', null, 'safe'::answer_choice, 'ما فيها رابط، وتوجهك لرقم تعرفه أنت.', false, 'Your bank', '11:40 AM', null, '245 SAR was charged to your card ending in 4417. If this wasn’t you, call the number on the back of your card.', 'No link, and it sends you to a number you already know.'),
('sms'::scenario_category, 'medium'::difficulty_level, '+966 54 610 7735', 'أمس', null, 'مخالفة مرورية غير مسددة بقيمة ٥٠٠ ريال. سددها خلال ٢٤ ساعة لتجنب مضاعفتها:', 'pay-traffic-ksa.net', 'scam'::answer_choice, 'المخالفات تنسدد من التطبيقات الرسمية، مو من رابط في رسالة.', false, null, 'Yesterday', null, 'Unpaid traffic fine of 500 SAR. Pay within 24 hours to avoid it doubling:', 'Fines are paid in official apps, not through a link in a message.'),
('sms'::scenario_category, 'medium'::difficulty_level, 'شركة الشحن', 'السبت', null, 'شحنتك رقم 7781 توصلك اليوم بين ٤ و٨ م. تتبعها من تطبيق شركة الشحن.', null, 'safe'::answer_choice, 'ما تطلب فلوس، وتوجهك للتطبيق مو لرابط.', false, 'Shipping company', 'Saturday', null, 'Your parcel 7781 arrives today between 4 and 8 PM. Track it in the shipping company’s app.', 'It doesn’t ask for money and points you to the app, not a link.'),
('sms'::scenario_category, 'medium'::difficulty_level, '+966 54 118 2290', '١٠:٤٥ ص', null, 'تعذّر توصيل شحنتك. حدّد موعد توصيل جديد من الرابط (رسوم ٥ ريال):', 'ksa-post-redeliver.com', 'scam'::answer_choice, 'رسوم صغيرة ورابط غريب. شركات الشحن ما تطلب دفع إعادة التوصيل برابط.', false, null, '10:45 AM', null, 'We couldn’t deliver your parcel. Pick a new delivery time at the link (5 SAR fee):', 'A small fee and a strange link. Couriers don’t charge re-delivery through links.'),
('sms'::scenario_category, 'medium'::difficulty_level, 'بوابة التوظيف', 'الاثنين', null, 'تم استلام طلبك للوظيفة رقم 4471. تقدر تتابع حالة طلبك من حسابك في البوابة.', null, 'safe'::answer_choice, 'تأكيد لطلب سويته، وتقول لك تدخل بنفسك.', false, 'Jobs portal', 'Monday', null, 'We received your application for job 4471. Track its status from your account on the portal.', 'A confirmation for something you did, and it tells you to log in yourself.'),
('sms'::scenario_category, 'medium'::difficulty_level, '+966 56 902 1147', '٨:٢٠ ص', null, 'تم تحديث نظام الهوية الرقمية. حدّث بياناتك خلال ٤٨ ساعة لتجنب تعليق الخدمات:', 'digital-id-update.net', 'scam'::answer_choice, 'الجهات الحكومية ما ترسل روابط تحديث، ونطاقها ينتهي بـ gov.sa.', false, null, '8:20 AM', null, 'The digital ID system was updated. Update your details within 48 hours to avoid suspension:', 'Government bodies don’t send update links, and their domains end in gov.sa.'),
('sms'::scenario_category, 'medium'::difficulty_level, '+966 53 661 4402', '١١:١٥ ص', null, 'وصلتك حوالة دولية بمبلغ ١٥٠٠ ريال. لاستلامها أكد بيانات بطاقتك:', 'transfer-receive-ksa.com', 'scam'::answer_choice, 'استلام الحوالة ما يحتاج بيانات بطاقتك.', false, null, '11:15 AM', null, 'You have an international transfer of 1500 SAR. Confirm your card details to receive it:', 'Receiving a transfer never needs your card details.'),
('sms'::scenario_category, 'medium'::difficulty_level, 'متجر الأجهزة', 'أمس', null, 'تم شحن طلبك رقم 88214 وبيوصل خلال ٣ أيام عمل. ما يحتاج أي دفع إضافي.', null, 'safe'::answer_choice, 'تأكيد شحن بدون أي طلب منك.', false, 'Electronics store', 'Yesterday', null, 'Your order 88214 has shipped and will arrive within 3 business days. No extra payment needed.', 'A shipping confirmation with no request.'),
('sms'::scenario_category, 'medium'::difficulty_level, '+966 55 448 7701', '٢:٤٠ م', null, 'تم حجز شحنتك في الجمارك. ادفع رسوم الجمارك ٣٢ ريال للإفراج عنها:', 'customs-fee-sa.info', 'scam'::answer_choice, 'رسوم الجمارك ما تنطلب من رقم عادي ورابط غريب.', false, null, '2:40 PM', null, 'Your parcel is held at customs. Pay a 32 SAR customs fee to release it:', 'Customs fees don’t come from a personal number with a strange link.'),
('sms'::scenario_category, 'medium'::difficulty_level, '+966 57 118 4430', 'الخميس', null, 'لديك قضية مسجلة باسمك. اطلع على تفاصيلها خلال ٢٤ ساعة لتجنب إيقاف الخدمات:', 'case-details-ksa.net', 'scam'::answer_choice, 'التخويف بقضية ورابط غريب. القضايا تطلع في المنصات الرسمية.', false, null, 'Thursday', null, 'There’s a case registered in your name. View the details within 24 hours to avoid suspension of services:', 'Scaring you with a case plus a strange link. Cases show up on official platforms.'),
('sms'::scenario_category, 'medium'::difficulty_level, 'مصرفك', '٣:٠٥ م', null, 'تم إلغاء عملية شراء بـ ١٢٠ ريال بناءً على طلبك. المبلغ بيرجع لحسابك خلال ٣ أيام عمل.', null, 'safe'::answer_choice, 'إشعار عن عملية سويتها، بدون رابط ولا طلب.', false, 'Your bank', '3:05 PM', null, 'A 120 SAR purchase was cancelled at your request. The amount returns to your account within 3 business days.', 'A notice about something you did, with no link and no request.'),
('sms'::scenario_category, 'medium'::difficulty_level, 'الخدمات الحكومية', 'الأحد', null, 'رخصة القيادة تنتهي بعد ٣٠ يوم. تقدر تجددها من التطبيق الحكومي الرسمي.', null, 'safe'::answer_choice, 'تذكير بدون رابط، ويوجهك للتطبيق الرسمي اللي تعرفه.', false, 'Government services', 'Sunday', null, 'Your driving license expires in 30 days. You can renew it in the official government app.', 'A reminder with no link, pointing you to the official app you know.'),
('sms'::scenario_category, 'hard'::difficulty_level, 'مصرفك', '٨:١٢ ص', null, 'تم إيقاف بطاقتك مؤقتاً لحمايتك. لإعادة التفعيل وثّق هويتك من هنا:', 'bank-secure-verify.com', 'scam'::answer_choice, 'اسم المرسل ممكن يتزوّر، والبنوك ما ترسل روابط توثيق.', false, 'Your bank', '8:12 AM', null, 'Your card was temporarily blocked for your protection. Verify your identity here to reactivate it:', 'Sender names can be faked, and banks don’t send verification links.'),
('sms'::scenario_category, 'hard'::difficulty_level, 'محفظتك الرقمية', 'أمس', null, 'رمز التحقق 739102 لإتمام دفع ١٨٩ ريال. لا تشارك الرمز مع أي أحد.', null, 'safe'::answer_choice, 'رمز لعملية أنت سويتها، ويحذرك من مشاركته.', false, 'Your digital wallet', 'Yesterday', null, 'Verification code 739102 to complete a 189 SAR payment. Don’t share it with anyone.', 'A code for something you did, with a warning not to share it.'),
('sms'::scenario_category, 'hard'::difficulty_level, 'مصرفك', '٩:٠٠ م', null, 'رمز التحقق 418230 لإضافة جهاز جديد. إذا ما كنت أنت، لا تشارك الرمز واتصل بالبنك.', null, 'safe'::answer_choice, 'يحذرك ويوجهك للبنك، وما يطلب منك ترسل الرمز.', false, 'Your bank', '9:00 PM', null, 'Verification code 418230 to add a new device. If this wasn’t you, don’t share the code and call your bank.', 'It warns you and points you to the bank. It doesn’t ask you to send the code.'),
('sms'::scenario_category, 'hard'::difficulty_level, 'شركة الشحن', '١:٢٥ م', null, 'شحنتك رقم 7781 تحتاج تأكيد العنوان. حدّثه من هنا:', 'shipping-ksa-address.co', 'scam'::answer_choice, 'اسم المرسل ممكن يتزوّر، والرابط مو موقع شركة الشحن.', false, 'Shipping company', '1:25 PM', null, 'Your parcel 7781 needs an address confirmation. Update it here:', 'Sender names can be faked, and the link isn’t the shipping company’s site.'),
('sms'::scenario_category, 'hard'::difficulty_level, 'منصة التوظيف', '١٠:٠٢ ص', null, 'رمز الدخول 290114. صالح لمدة ٥ دقايق. لا تعطيه لأحد.', null, 'safe'::answer_choice, 'رمز دخول طلبته أنت، ومعه تحذير.', false, 'Jobs platform', '10:02 AM', null, 'Login code 290114. Valid for 5 minutes. Don’t give it to anyone.', 'A login code you asked for, with a warning.'),
('sms'::scenario_category, 'hard'::difficulty_level, 'مصرفك', '١١:١٨ ص', null, 'تم تحويل ١٥٠٠ ريال إلى حساب ينتهي بـ 3390. إذا ما كانت العملية منك، اتصل على الرقم اللي خلف بطاقتك.', null, 'safe'::answer_choice, 'إشعار بدون رابط، ويوجهك لرقم تعرفه.', false, 'Your bank', '11:18 AM', null, '1500 SAR was transferred to an account ending in 3390. If this wasn’t you, call the number on the back of your card.', 'A notice with no link, pointing you to a number you know.'),
('sms'::scenario_category, 'hard'::difficulty_level, 'مصرفك', '١٠:٥٠ م', null, 'رصيدك في برنامج المكافآت ٢٤٠٠ نقطة ينتهي الليلة. حوّلها لرصيد من:', 'rewards-bank-sa.com', 'scam'::answer_choice, 'الاستعجال والرابط علامتين، حتى لو اسم المرسل اسم البنك.', false, 'Your bank', '10:50 PM', null, 'Your 2400 rewards points expire tonight. Convert them to credit at:', 'Urgency plus a link are two signs, even if the sender says it’s your bank.'),
('sms'::scenario_category, 'hard'::difficulty_level, 'شركة الاتصالات', '٩:١٥ ص', null, 'تم طلب نقل رقمك لمشغل آخر. إذا ما كان الطلب منك، رد على الرسالة بـ 0 خلال ساعة.', null, 'safe'::answer_choice, 'ما فيها رابط ولا تطلب بيانات، وتعطيك طريقة ترفض فيها.', false, 'Telecom company', '9:15 AM', null, 'A request was made to move your number to another carrier. If this wasn’t you, reply 0 within an hour.', 'No link and no request for details. It gives you a way to refuse.'),
('sms'::scenario_category, 'hard'::difficulty_level, 'شركة الاتصالات', '٦:٣٠ م', null, 'بمناسبة اليوم الوطني، لك ٥٠ جيجا هدية. فعّلها من:', 'telecom-sa.gift-offer.co', 'scam'::answer_choice, 'اسم المرسل ممكن يتزوّر، والرابط ينتهي بـ gift-offer.co.', false, 'Telecom company', '6:30 PM', null, 'For National Day, enjoy 50 GB free. Activate it at:', 'Sender names can be faked, and the link ends in gift-offer.co.'),
('sms'::scenario_category, 'hard'::difficulty_level, 'مصرفك', '١١:٤٨ م', null, 'تمت محاولة دخول لحسابك من جهاز غير معروف. إذا ما كنت أنت، أوقف الجهاز من هنا:', 'bank.com.sa-secure.help', 'scam'::answer_choice, 'تشبه التنبيه الحقيقي، بس فيها رابط، والنطاق ينتهي بـ secure.help.', false, 'Your bank', '11:48 PM', null, 'Someone tried to log in to your account from an unknown device. If this wasn’t you, block the device here:', 'It looks like a real alert, but it has a link, and the domain ends in secure.help.'),
('sms'::scenario_category, 'hard'::difficulty_level, 'منصة التوظيف', '١٠:٠٤ ص', null, 'رمز الدخول 731905. إذا ما طلبته، ألغِ الطلب من الرابط:', 'cancel-otp-request.com', 'scam'::answer_choice, 'الرسالة الحقيقية تقول لك تتجاهلها، مو تلغي الرمز من رابط.', false, 'Jobs platform', '10:04 AM', null, 'Login code 731905. If you didn’t ask for it, cancel the request at the link:', 'A real message tells you to ignore it, not to cancel the code through a link.'),
('sms'::scenario_category, 'hard'::difficulty_level, 'مصرفك', '٢:١٥ م', null, 'تم إيقاف بطاقتك مؤقتاً بعد ٣ محاولات خاطئة للرقم السري. لإعادة التفعيل استخدم التطبيق أو الصراف.', null, 'safe'::answer_choice, 'تنبيه مخيف بس ما فيه رابط ولا رقم، ويوجهك لقنواتك.', false, 'Your bank', '2:15 PM', null, 'Your card was temporarily blocked after 3 wrong PIN attempts. Use the app or an ATM to reactivate it.', 'A scary alert, but with no link or number, and it points you to your usual channels.'),
('whatsapp'::scenario_category, 'easy'::difficulty_level, '+44 7911 123456', 'واتساب · ١٠:٠٥ ص', null, 'السلام عليكم، معك شركة توظيف. نوظفك من البيت بـ ٥٠٠ ريال يومياً، بس ادفع رسوم تسجيل ١٠٠ ريال.', null, 'scam'::answer_choice, 'رقم دولي غريب، وعرض كبير يطلب رسوم مقدماً.', false, null, 'WhatsApp · 10:05 AM', null, 'Hello, this is a recruitment company. Work from home for 500 SAR a day. Just pay a 100 SAR registration fee.', 'A strange international number and a big offer that asks for a fee upfront.'),
('whatsapp'::scenario_category, 'easy'::difficulty_level, 'العيادة · حساب أعمال موثّق', 'واتساب · ٤:١٠ م', null, 'تأكيد موعدك الثلاثاء ٥ م مع الطبيبة سارة. للإلغاء اكتب: إلغاء.', null, 'safe'::answer_choice, 'حساب أعمال موثّق، ويأكد موعد حجزته.', false, 'Clinic · verified business', 'WhatsApp · 4:10 PM', null, 'Confirming your appointment on Tuesday at 5 PM with Dr. Sarah. To cancel, type: cancel.', 'A verified business account confirming an appointment you booked.'),
