('websites'::scenario_category, 'medium'::difficulty_level, 'https://store-sa.checkout-secure.net', '', 'إتمام الطلب', 'ادخل بيانات بطاقتك ورمز التحقق لإكمال طلبك.', null, 'scam'::answer_choice, 'اسم المتجر جاي قبل نطاق ثاني. الموقع الحقيقي ينتهي بـ store.sa.', false, null, '', 'Checkout', 'Enter your card details and verification code to complete your order.', 'The store’s name comes before another domain. The real site ends in store.sa.'),
('websites'::scenario_category, 'medium'::difficulty_level, 'https://www.uni.edu.sa/admission', '', 'بوابة القبول', 'يفتح التسجيل للفصل القادم ١ يناير. التقديم مجاني.', null, 'safe'::answer_choice, 'نطاق edu.sa رسمي، وما يطلب فلوس.', false, null, '', 'Admissions portal', 'Registration for next term opens on January 1. Applying is free.', 'An official edu.sa domain, and it asks for no money.'),
('websites'::scenario_category, 'medium'::difficulty_level, 'https://bank.com.sa.login-secure.app', '', 'الخدمات المصرفية', 'ادخل اسم المستخدم وكلمة المرور ورمز التحقق.', null, 'scam'::answer_choice, 'النطاق الحقيقي آخر جزء: login-secure.app، مو bank.com.sa.', false, null, '', 'Online banking', 'Enter your username, password and verification code.', 'The real domain is the last part: login-secure.app, not bank.com.sa.'),
('websites'::scenario_category, 'medium'::difficulty_level, 'https://www.airline.sa/manage', '', 'إدارة الحجز', 'ادخل رقم الحجز واسم العائلة عشان تعدّل رحلتك.', null, 'safe'::answer_choice, 'موقع شركة تعرفها، ويطلب معلومات الحجز بس.', false, null, '', 'Manage booking', 'Enter your booking reference and last name to change your flight.', 'A company site you know, asking only for booking info.'),
