('websites'::scenario_category, 'hard'::difficulty_level, 'https://www.bankk.com.sa/login', '', 'الخدمات المصرفية', 'ادخل اسم المستخدم وكلمة المرور للخدمات المصرفية.', null, 'scam'::answer_choice, 'حرف مكرر في اسم البنك. قارن الرابط حرف حرف.', false, null, '', 'Online banking', 'Enter your username and password for online banking.', 'A doubled letter in the bank’s name. Compare the link letter by letter.'),
('websites'::scenario_category, 'hard'::difficulty_level, 'https://www.bank.com.sa/login', '', 'الخدمات المصرفية', 'ادخل اسم المستخدم وكلمة المرور للخدمات المصرفية.', null, 'safe'::answer_choice, 'نفس النطاق اللي تعرفه، بدون حروف زايدة.', false, null, '', 'Online banking', 'Enter your username and password for online banking.', 'The same domain you know, with no extra letters.'),
