('websites'::scenario_category, 'hard'::difficulty_level, 'https://permits.city.gov.sa', '', 'طلب تصريح', 'قدّم طلب التصريح، والسداد يكون من قنوات السداد الحكومية.', null, 'safe'::answer_choice, 'نطاق gov.sa، والسداد من قنوات رسمية.', false, null, '', 'Permit request', 'Submit your permit request. Payment is through government payment channels.', 'A gov.sa domain, with payment through official channels.'),
('websites'::scenario_category, 'hard'::difficulty_level, 'https://store.sa-offers.com', '', 'عروض المتجر', 'خصم ٧٠٪ للأعضاء. سجّل دخول بحسابك في المتجر.', null, 'scam'::answer_choice, 'store.sa-offers.com نطاق مختلف عن store.sa.', false, null, '', 'Store offers', '70% off for members. Log in with your store account.', 'store.sa-offers.com is a different domain from store.sa.'),
('websites'::scenario_category, 'hard'::difficulty_level, 'https://www.citylibrary.sa/account/login', '', 'دخول المكتبة', 'سجّل دخول بحساب المكتبة عشان تجدد كتبك.', null, 'safe'::answer_choice, 'نفس نطاق المكتبة اللي تعرفه.', false, null, '', 'Library login', 'Log in with your library account to renew your books.', 'The same library domain you know.'),
('sms'::scenario_category, 'easy'::difficulty_level, '+966 55 384 2917', 'رسالة نصية · ١١:٤٢ ص', null, 'عميلنا العزيز، تم إيقاف بطاقتك مؤقتاً. حدّث بياناتك خلال ٢٤ ساعة عبر الرابط…', null, 'scam'::answer_choice, 'رابط واستعجال وطلب بيانات.', true, null, 'SMS · 11:42 AM', null, 'Dear customer, your card has been temporarily blocked. Update your details within 24 hours using the link…', 'A link, urgency and a request for details.'),
('sms'::scenario_category, 'easy'::difficulty_level, 'رمز التحقق', 'رسالة نصية · ١١:٣٠ ص', null, 'رمز التحقق لتسجيل الدخول: 482916. لا تشاركه مع أحد، حتى لو قال إنه من الدعم.', null, 'safe'::answer_choice, 'رمز طلبته أنت، ومعه تحذير.', true, 'Verification code', 'SMS · 11:30 AM', null, 'Login code: 482916. Don’t share it with anyone, even if they say they’re from support.', 'A code you asked for, with a warning.'),
('whatsapp'::scenario_category, 'easy'::difficulty_level, '+966 50 771 0264', 'واتساب · أمس', null, 'مبروك! ربحت ٥٠٠٠ ريال في سحب العملاء. أرسل رقم الآيبان عشان نحوّل لك المبلغ.', null, 'scam'::answer_choice, 'جائزة ما شاركت فيها وطلب آيبان.', true, null, 'WhatsApp · Yesterday', null, 'Congrats! You won 5000 SAR in our customer draw. Send your IBAN so we can transfer it.', 'A draw you never entered, and a request for your IBAN.');
